WITH RECURSIVE Months AS (SELECT 1 AS month UNION ALL SELECT month + 1 FROM Months WHERE month < 12), ActiveDrivers AS (SELECT m.month, (SELECT COUNT(*) FROM Drivers d WHERE d.join_date <= LAST_DAY(CONCAT('2020-', LPAD(m.month, 2, '0'), '-01'))) AS active_count FROM Months m), WorkingDrivers AS (SELECT m.month, (SELECT COUNT(DISTINCT ar.driver_id) FROM AcceptedRides ar JOIN Rides r ON ar.ride_id = r.ride_id WHERE YEAR(r.requested_at) = 2020 AND MONTH(r.requested_at) = m.month) AS working_count FROM Months m) SELECT a.month, ROUND(IFNULL(w.working_count * 100.0 / NULLIF(a.active_count, 0), 0), 2) AS working_percentage FROM ActiveDrivers a JOIN WorkingDrivers w ON a.month = w.month ORDER BY a.month;
